function L(module,id,title,summary,sections,steps,trap,worked,quiz,refs=[],code=''){
 expansionLessons.push({module,id,title,summary,level:'P0',foundation:sections,points:steps.map(s=>s.split('。')[0]+'。'),tutorial:{question:summary,steps,trap,worked:{prompt:worked[0],answer:worked[1]}},quiz:quiz.map((q,i)=>({id:id+'-q'+(i+1),prompt:q[0],options:q[1],answer:q[2],explain:q[3]})),refs:refs.map(i=>expansionSources[i]),code});
}
const S=(title,...paragraphs)=>({title,paragraphs});
const T=(title,heads,rows)=>({title,paragraphs:[],table:{heads,rows}});
L('linux','linux-start','01 · Linux、程序、进程和线程','从磁盘上的程序文件，到 CPU 正在执行的一条指令，中间发生了什么？',[
 S('先把四个名字分开','Linux 内核负责调度 CPU、管理内存和驱动硬件。Shell 是接收命令的用户程序；终端是输入和显示文字的界面；发行版把内核、工具和软件组织在一起。它们不是同一个东西。','程序是磁盘上的指令和数据文件，例如编译出的 a.out。进程是程序的一次运行：同一个程序可以启动两次，形成不同 PID 的进程。PID 是进程编号，不是程序文件名。'),
 S('线程为什么既共享又会冲突？','同一进程内的线程共享地址空间，所以一个线程改全局变量，另一个能访问同一对象。每个线程又有自己的执行位置、寄存器上下文和栈。共享让通信方便，也让无同步的同时修改变得危险。','例如两个线程各做一次 count++：它包含读取、加一、写回。两者都读到 0 后都写 1，就丢失一次更新。C/C++ 中无同步的数据竞争还可能产生未定义行为，不能只按这个交错模型预测结果。'),
 T('哪些资源放在哪里？',['项目','独立进程（普通私有内存）','同一进程的线程'],[['全局变量/堆','逻辑上分离；共享映射另论','共享'],['栈与执行位置','各自持有','各线程持有自己的栈与上下文'],['文件描述符表','fork 后各有一张表，底层可共享','通常共享进程的描述符表']]),
 S('用户态为什么需要系统调用？','普通应用不能随意访问内核或物理外设。read、write 等接口让应用请求内核服务；内核检查权限和参数后执行。函数调用不一定是系统调用，例如 strlen 主要在用户空间数字符。')
],['先识别对象：文件里的程序、运行中的进程、进程内的线程。不要仅凭同一个函数名就认定同一个执行实体。','再判断资源是否共享；线程修改共享数据需要同步，进程通信则要选择明确的 IPC 机制。','最后区分用户代码和内核服务：一次库函数调用可能不进入内核，也可能包装系统调用。'], '线程有独立栈，并不表示栈内地址绝对不能被其他线程访问；仍要考虑地址共享和对象生命周期。', ['同一可执行文件启动两次，修改第一次运行的普通全局变量，会自动改第二次的吗？','不会。两个进程的普通私有地址空间相互隔离；若要共享，需显式使用共享映射等机制。'],[
 ['程序与进程的关系正确的是？',['一个程序只能运行一次','同一程序可有多个进程实例','进程就是文件路径','PID 就是源代码行号'],1,'程序是静态文件，进程是运行实例。'],
 ['同一进程的线程通常共享？',['执行位置','各自的寄存器值','全局变量和堆','各自的调用栈内容副本'],2,'地址空间共享，独立执行上下文不等于独立进程。'],
 ['strlen 一定需要系统调用吗？',['不需要，它可直接读用户内存','每个字符都要进入内核','必须 fork','必须打开设备树'],0,'求字符串长度通常只访问已有用户数据。']
],[4]);
L('linux','linux-shell','02 · 路径、权限与常见命令','看到 rwxr-x---、chmod 640、重定向和管道时，怎样逐项读懂？',[
 S('路径从哪里开始？','绝对路径从 / 开始；相对路径从当前工作目录开始。pwd 查看当前目录，cd 改变目录，ls -l 查看文件类型和权限。./app 表示当前目录下的 app；直接写 app 通常要由 Shell 按 PATH 查找。','/dev 常见设备节点，/proc 提供进程和内核运行信息，/sys 提供设备模型等信息。不能把 /proc 下内容都当成磁盘上固定保存的普通文件。'),
 T('权限先分对象，再看 r/w/x',['权限','普通文件','目录'],[['r','读内容','列出目录项名称'],['w','改内容','配合 x 创建/删除目录项，还受 sticky 等限制'],['x','允许执行（还受格式、解释器等约束）','搜索/穿过目录，按名称访问子项']]),
 S('八进制权限怎样算？','r=4、w=2、x=1，每组三位相加。640 表示所有者 rw-、所属组 r--、其他人 ---。实际检查还要考虑用户身份、父目录的搜索权限、ACL 等。删除文件主要看父目录，而非仅看文件是否可写。','ps 看进程，top 看运行负载，grep 找文本，find 按条件找文件，dmesg 看内核日志（可能需要权限），man 2 fork 查看第二节系统调用手册。不要把 chmod +x 当成“任何文件都会变成合法程序”。'),
 S('重定向顺序是有意义的','cmd >out 2>&1：先把标准输出 1 指向 out，再让标准错误 2 复制当前的 1。cmd 2>&1 >out：先让 2 指向原来的标准输出，再改变 1，因此错误不一定进入 out。管道 | 通常连接左侧标准输出和右侧标准输入。')
],['先用 pwd 和路径形式确定目标，再看每级目录是否允许搜索。','把权限按所有者、组、其他人三组拆开；目录上的 x 与普通文件的 x 含义不同。','按从左到右解释重定向，记住 0/1/2 分别约定为标准输入、标准输出、标准错误。'],'能够读文件不代表能够删除它；Linux 权限还可能受 ACL、挂载选项等约束。',['chmod 750 后，所属组能做什么？','组的数字是 5=4+1，因此是 r-x。对普通可执行文件表示允许读和执行；对目录表示可列名称并搜索，不能仅据此新建目录项。'],[
 ['640 中所有者权限为？',['rwx','r--','rw-','--x'],2,'6=4+2，所以是读和写。'],
 ['目录 x 权限主要表示？',['运行目录代码','搜索或穿过该目录','清空目录','更改所有者'],1,'访问目录中的命名对象通常需要搜索权限。'],
 ['标准错误通常对应哪个描述符？',['0','1','3','2'],3,'0 stdin、1 stdout、2 stderr 是约定。']
],[5,7]);
L('linux','linux-fork','03 · fork：一次调用，两个返回分支','为什么一行 fork() 后，父进程和子进程都继续执行？',[
 S('先读函数类型','pid_t fork(void)：pid_t 是存放进程编号的整数类型，void 表示不传参数。把返回值存入 pid，用它判断“我是父进程还是子进程”。fork 成功时新建子进程，两者从 fork 返回的位置继续，子进程不会重新从 main 第一行开始。'),
 T('同一行在两边得到不同值',['执行者/结果','返回值','应该做什么'],[['父进程成功','子进程的 PID，大于 0','保存 PID，管理/等待子进程'],['子进程','0','执行子进程的工作'],['创建失败','-1，设置 errno','处理失败，没有子进程产生']]),
 S('变量为什么看着一样，却改不到对方？','假设 fork 前 x=7，父子起初都能读到 7。子进程把自己的 x 改成 9，父进程的普通私有 x 仍为 7。Linux 通常用写时复制：先共享物理页面，发生写入时再隔离需要改变的页，以减少马上完整复制的成本。','写时复制是实现优化，不是“父子共享普通变量”的接口保证。显式 MAP_SHARED 映射等是另一种情况。调度先后未确定，不能仅靠父代码写在前面就断言父先打印。'),
 S('连续 fork 与 printf 缓冲陷阱','无条件执行两次 fork，且全部成功、没有提前退出，进程数量按 1→2→4 增长。带 if、短路 &&/|| 或失败处理时，要逐分支画树。','fork 前还没刷出的 stdio 缓冲会复制进子进程。若父子之后都正常退出并刷出缓冲，同一段字可能重复。输出次数题先看调用次数，再看缓冲与退出方式；换行在重定向到文件时不一定立即刷新。')
],['在 fork 这一行分叉，并分别标上父返回正数、子返回 0；失败则没有分叉。','在每条分支上独立执行后续语句，普通变量也分别跟踪。','最后数存活进程和输出调用；额外检查缓冲、条件分支及等待关系。'],'多线程进程 fork 后，子进程只有调用 fork 的那个线程；exec 前应遵循异步信号安全限制，不能照搬简单单线程示例。',['全部 fork 成功：if (fork()==0) fork(); 最终包括原进程共有几个进程？','3 个。第一次产生父 P 和子 C；只有 C 满足 ==0 再产生 D。P 不执行第二次 fork，所以不能机械套 2²。'],[
 ['子进程从成功的 fork 得到？',['自己的 PID','父 PID','0','-1'],2,'0 是子分支标识；真正的自身 PID 用 getpid 获取。'],
 ['fork 失败时产生几个新子进程？',['0','1','2','不确定但至少1'],0,'父返回 -1，没有新子进程。'],
 ['子修改普通私有变量后，父变量？',['必定同步更新','仍独立，不能靠此通信','变为0','变为随机数'],1,'逻辑地址空间独立，写时复制不改变这个接口语义。']
],[0,12]);
L('linux','linux-exec','04 · exec 系列：换程序，不换进程身份','你提到的“exe 函数”，这里先按常考的 exec 系列学习。',[
 S('fork 负责生，exec 负责换','fork 创建子进程；exec 系列把调用者当前执行的程序替换成另一个程序。成功后 PID 保留，新程序按自己的入口开始运行。旧程序的下一行不会再执行。这里的 exec 与 Windows 文件扩展名 .exe 是两件事。','失败时，函数返回 -1，原程序还在，errno 说明失败原因。常见原因包括文件不存在、无执行权限、格式不支持。不能把 exec 后的打印当成“新程序执行完再回来”。'),
 T('记字母，不死背函数名',['后缀','含义','例子'],[['l','list：参数逐个写在调用里，以 (char *)NULL 结束','execl(path, "app", "arg", (char *)NULL)'],['v','vector：用以 NULL 结束的指针数组传 argv','execv(path, argv)'],['p','文件名不含 / 时按 PATH 搜索','execvp("ls", argv)'],['e','显式传 envp 环境变量数组','execve(path, argv, envp)']]),
 S('char *argv[] 到底是什么？','argv 是“指向字符的指针”组成的数组。每个 argv[i] 指向一个以 \\0 结束的字符串；数组最后再放一个 NULL 指针表示没有更多参数。字符串结束符与指针数组结束标记不是同一层。','例如 char *args[]={"ls","-l",NULL}; args[0] 通常写程序名，args[1] 是选项，args[2] 是终止指针。execvp("ls",args) 不会自动解析 Shell 的 |、> 或通配符，它把数组里的字符串当参数传给程序。'),
 S('为什么常常组合 fork 和 exec？','Shell 希望自己继续接收命令，同时启动另一个程序，所以先 fork，再让子进程 exec，父进程 waitpid。若 Shell 自己直接 exec 成功，它就被新程序替换了。打开的描述符默认可能保留；带 FD_CLOEXEC 的在成功 exec 时关闭。')
],['先看是否调用 fork，确定进程数量；单独 exec 不增加进程。','逐项组织 argv 并加末尾 NULL；按是否需要 PATH/自定义环境选择变体。','把 exec 后面的代码视为失败处理路径；父进程另行 waitpid 回收。'],'exec 成功时不返回，失败时才返回 -1。这里的 p 不是“创建 process”，而是 PATH 搜索。',['子 PID 为 210，execv 成功后程序 B 的 PID 是多少？原来的下一行会运行吗？','仍为 210。被替换的是程序映像，进程身份保留；原来的下一行不执行。若 execv 返回，才进入原代码的错误处理。'],[
 ['exec 成功后怎样返回？',['返回0','返回新 PID','返回原 main','不返回到旧程序'],3,'旧程序映像被替换。'],
 ['execvp 中 p 的含义？',['按 PATH 搜索','改变优先级','管道','父进程'],0,'当文件名不含 / 时按 PATH 查找。'],
 ['argv 最后一项应该是？',['字符0','NULL 指针','一个空格','字符串 EOF'],1,'每个参数自身是字符串，参数数组以空指针结束。']
],[1,2]);
L('linux','linux-wait','05 · waitpid、僵尸进程与退出状态','子进程已经结束，为什么父进程还需要等待或回收它？',[
 S('“结束”和“回收”不是同一时刻','子进程退出后，内核保留供父读取的退出信息；尚未被回收时可能显示为僵尸 Z。它不再执行用户代码，不能靠再次杀死它解决根本问题。父进程应使用 wait/waitpid 等接口取走状态。','父先退出，而子仍运行，叫孤儿情形；Linux 会把它重新托管给合适的收养进程，例如子收割者或 init。孤儿和僵尸不能按名字混为一谈。'),
 T('waitpid(pid,&status,options) 的返回值',['返回值','解释'],[['>0','本次收集到状态的子进程 PID'],['0','使用 WNOHANG 且匹配子进程尚无可报告状态'],['-1','失败，如 EINTR 或没有符合条件的子进程 ECHILD']]),
 S('status 为什么不能直接当退出码？','status 编码了退出、信号终止等信息。先用 WIFEXITED(status) 判断正常退出，再用 WEXITSTATUS(status) 提取退出码；若 WIFSIGNALED，则用 WTERMSIG。只有相应条件成立时，读取对应字段才有意义。','等待被信号中断且 errno==EINTR 时通常重试。WNOHANG 的 0 不表示“子进程退出码为 0”，而表示现在没有可报告状态。非阻塞轮询要配合事件/等待策略，不能永久忙循环。'),
 S('exit 和 _exit 的区别','exit 会进行 C 库层面的正常清理，如刷新 stdio、调用已注册退出处理；_exit 结束进程而不执行这些用户态清理。fork 后子分支 exec 失败常用 _exit(127)，避免把继承的 stdio 缓冲再次刷出。127 是程序选用的约定值，不是内核强制的 exec 返回值。')
],['创建后保存子 PID，明确由谁负责回收；主流程需要子结果时阻塞等待也很自然。','检查 waitpid 返回值，EINTR 重试，其余错误单独处理；WNOHANG 的 0 不读作退出码。','先判退出类型再取值；把“正在运行的孤儿”与“已退出待回收的僵尸”分开。'],'在正常 SIGCHLD 处理设定下讨论僵尸；显式 SIG_IGN、SA_NOCLDWAIT 等配置会改变回收行为。',['waitpid 返回子 PID，WIFEXITED 为真，WEXITSTATUS 为 7，应该怎样表述？','成功回收该子进程，它正常调用退出流程并给出状态码 7；“正常退出”表示不是被信号终止，不表示业务处理成功。'],[
 ['WNOHANG 返回0表示？',['退出码0','现在无可报告状态','发生 EINTR','父进程退出'],1,'必须先看函数返回，再解释 status。'],
 ['僵尸进程仍在执行任务吗？',['是','只执行中断','不再执行用户代码','会自动变成线程'],2,'主要保留退出状态等回收信息。'],
 ['提取正常退出码前应检查？',['WIFEXITED','sizeof(pid)','WNOHANG==0','status==PID'],0,'状态编码须使用对应宏解码。']
],[3]);
L('linux','linux-fd','06 · 文件描述符、dup2 与短读短写','fd 是整数，为什么复制一个 fd 会共享文件偏移？',[
 S('三层关系先画出来','应用拿到 fd，例如 3；它是进程描述符表里的索引。表项引用内核中的打开文件描述，其中记录文件偏移和状态标志；打开文件描述再关联实际文件。fd 不是文件内容本身。','dup/dup2 产生另一个指向同一打开文件描述的描述符，所以共享偏移。fork 继承的对应描述符也如此。两次独立 open 同一路径通常产生不同打开文件描述，偏移独立。'),
 S('dup2 为什么能重定向？','dup2(fd,1) 让标准输出这个编号引用 fd 对应的对象；必要时原子地关闭旧的 1 并替换。之后写 1 就写到新目标。若 fd==1，成功时是无操作，之后不能不加判断地 close(fd)，否则就把输出关了。'),
 S('read/write 返回的是实际完成字节数','read(fd,buf,100) 的 100 是最多读取多少，并非保证收到 100。正数是实际数量；在普通字节流且请求长度大于0时，0 通常表示到达 EOF；-1 是错误。write 同样可能只写一部分。','使用 ssize_t 接收返回值，因为要表达 -1。把 -1 存入 size_t 可能变成很大的正数，再拿来移动指针就危险。要维护已处理偏移，EINTR 重试；非阻塞 EAGAIN 则等待就绪，不能当成全部完成。')
],['分开 fd、打开文件描述和文件实体；判断共享发生在哪一层。','读写时累积实际返回值，只有正数才能增加偏移，错误先检查 errno。','关闭当前描述符只释放本表项引用；仍有其他引用时，不等于底层对象立即消失。'],'stdio 的 FILE* 与内核 fd 不是同一种对象；混用读写时还需考虑用户态缓冲。',['a=open(...); b=dup(a); 从 a 读2字节后，从 b 读1字节从哪里开始？','同一打开文件描述的偏移已前进2字节，因此 b 接着读第3个字节。若 b 是另一次独立 open，则不因 a 的读取而同步偏移。'],[
 ['dup 后共享的常见状态是？',['局部变量','文件偏移','指针地址','栈顶'],1,'引用同一打开文件描述。'],
 ['read 返回值应使用？',['char','unsigned int','ssize_t','文件名字符串'],2,'需要表达非负字节数及 -1 错误。'],
 ['write 返回比请求小的正数，应？',['从剩余位置继续','把它当全部成功','从头重复写全部','清零文件'],0,'从头重写会重复已完成部分。']
],[6,7,9,10]);
L('linux','linux-ipc','07 · 管道、共享内存与信号','父子不能靠普通变量通信，那怎样把数据交给对方？',[
 S('匿名管道是一条字节通道','pipe(p) 填入两个描述符：p[0] 读，p[1] 写。一般在 fork 前创建，父子才都继承需要的端点。父写子读时，父关闭读端，子关闭写端；所有进程都要关闭自己不用的副本。','管道缓冲为空且仍存在写端引用时，阻塞 read 会等待；当所有写端引用都关闭且缓冲读空，read 才返回 0。子进程忘关自己继承的写端，就可能永远等不到 EOF。'),
 T('按需求选通信方式',['方式','适合什么','需要补什么'],[['管道/套接字','传送字节流','长度协议、短读短写、关闭端点'],['共享内存','双方访问同一映射数据','锁/原子操作、所有权、内存可见性'],['信号','通知发生了某件事','处理函数安全、合并语义、同步方式']]),
 S('共享内存快，为什么仍需要锁？','“能看到同一片数据”不等于“每次修改完整且顺序正确”。生产者写完内容后才发布可读标记，消费者处理后再归还；同步原语负责约束访问与可见性。只加 volatile 不能把多个线程/进程间的数据协议变正确。'),
 S('信号处理函数不能随便 printf','信号可能打断正执行到一半的库函数。处理函数再次进入非安全函数可能破坏内部状态；常见简单方式是设置 volatile sig_atomic_t 标记，由普通流程处理工作。复杂通知可考虑 sigwait、signalfd 等相应模型。普通信号还可能合并，不应把它当精确计数器。')
],['确定通信方向和数据边界；字节流没有自动的“消息一包”。','画出每个进程持有的端点，把不用的全部关掉，再分析 EOF 与阻塞。','共享内存另配同步；信号只执行允许的轻量操作，把复杂工作留给正常流程。'],'多个写者向管道写入时，PIPE_BUF 的原子写保证不等于一次 read 对应一次 write；读取仍需协议。',['父已经 close(p[1])，子仍读不到 EOF，首先查什么？','查所有进程是否还有写端副本，包括子自己继承的 p[1]。同时确认管道中的剩余数据是否已经读空。'],[
 ['pipe 的 p[0] 用于？',['写','读','保存 PID','保存错误码'],1,'p[0] 读，p[1] 写。'],
 ['管道空且存在写端，阻塞读通常？',['返回EOF','退出进程','等待数据或写端关闭','自动扩容'],2,'空与 EOF 不同。'],
 ['volatile 能独自保证共享数据同步吗？',['不能','能解决所有竞争','等价于互斥锁','等价于消息队列'],0,'它不提供所需的原子性和线程间同步协议。']
],[8,12]);
L('linux','linux-io','08 · 阻塞、非阻塞与 epoll','“不会一直等”和“通知可读了”分别是谁负责的？',[
 S('两个不同维度','阻塞/非阻塞描述一次 I/O 调用在暂时无法完成时怎么做。非阻塞读暂时无数据，通常返回 -1 并设置 EAGAIN 或 EWOULDBLOCK；它不是 EOF。','select、poll、epoll 让程序等多个描述符的就绪事件。收到可读通知后仍要调用 read/recv，并检查实际结果；通知不是数据，也不保证整条应用报文已到齐。'),
 T('LT 与 ET 用水杯来理解',['模式','简化含义','应用要做什么'],[['LT 水平触发','只要可读条件仍成立，就可继续报告','仍正确处理短读、EOF、错误'],['ET 边沿触发','关注就绪状态变化','常配非阻塞描述符，循环读到 EAGAIN，再等待新事件']]),
 S('为什么 ET 只读一次可能卡住？','假设收到10字节，只读走4字节，剩6字节还在内核缓冲。若等不到下一次相关状态变化，应用可能一直等待，却没把已有数据读完。循环读取直到 EAGAIN，是明确确认“此刻已取尽可取数据”。','EOF、错误、对端关闭要单独处理；负载很高时还要考虑公平调度，不能让一个连接无限占用处理线程。不要把 epoll 简化成“任何场景都 O(1) 且一定比 poll 快”。')
],['先问调用是否阻塞，再问怎样同时等待多个对象；这两件事可以组合。','事件返回后执行 I/O，按正数、0、-1 分类处理，不凭事件名推断完整报文。','ET 模式用非阻塞读取排空到 EAGAIN；解析器保存半包状态。'],'普通文件与网络套接字的就绪行为不同；本课 ET 案例讨论流式套接字等适用对象。',['非阻塞 socket 的 read 返回 -1、errno=EAGAIN，应该关闭连接吗？','不能仅据此关闭。它表示现在没有可读数据，应回到事件等待；返回0的 EOF、真正错误和协议失败才按各自规则处理。'],[
 ['EAGAIN 与 EOF 是一回事吗？',['是','只有TCP相同','不是','只在32位相同'],2,'暂时无数据不等于流结束。'],
 ['epoll 可读事件意味着？',['整条消息完整','可以尝试读取并检查结果','数据已在用户缓冲','再也不会阻塞或报错'],1,'就绪与应用消息边界不同。'],
 ['ET 常用处理方式？',['只读1字节','只数事件','不调用read','非阻塞读到EAGAIN'],3,'避免遗漏缓冲中仍未消费的数据。']
],[11,9]);
L('linux','linux-devicetree','09 · 设备树：从 DTS 到驱动匹配','内核怎样知道板子上挂了哪个设备、地址在哪里？',[
 S('设备树是在描述硬件','驱动代码负责操作某类设备，设备树提供这块板子上设备的连接和资源信息。例如同一控制器在两块板子上可能接不同外设；把板级描述独立出来，内核不必为每种接线都重写一份驱动。','DTS 是便于人编辑的设备树源码；DTSI 常用于复用公共片段；DTC 是编译工具；DTB 是交给启动流程使用的二进制树。典型嵌入式 Linux 流程由 bootloader 把 DTB 交给内核。设备树不是 C 代码，也不是驱动执行顺序脚本。'),
 T('读节点时逐项找含义',['字段','如何理解'],[['sensor@48','节点名；@ 后 unit-address 需按总线规则匹配地址'],['compatible','从具体到较通用的硬件标识，供对应总线/驱动匹配'],['reg','父总线地址空间中的地址与可选长度，按父节点 cell 配置解释'],['status = "okay"','启用描述；不保证驱动一定成功'],['label: 与 &label','源码标签及引用，常用于控制器、时钟、GPIO 等关系']]),
 S('reg 为什么有时一个数，有时多个？','cell 是设备树编码里的32位单元。父节点 #address-cells 决定一个子地址用几个 cell，#size-cells 决定长度用几个。若父配置分别是1和1，reg=<0x4000 0x100> 表示总线地址0x4000、范围0x100；不能无条件把第二个数解释成另一个地址。','在常见 I²C 控制器节点中，#address-cells=1、#size-cells=0，子设备 reg=<0x48> 通常表示从机地址，不是 CPU 内存地址。CPU 物理地址转换还可能涉及 ranges。中断、GPIO 编码也必须看控制器 binding，不能任意填数字。'),
 S('设备没起来，按链路查','确认实际启动加载了哪个 DTB → 节点及父节点状态/结构 → compatible 和对应驱动是否存在 → 总线资源/时钟/复位/pinctrl → probe 日志。源码改对但 bootloader 仍加载旧 DTB，是很实际的故障。完整属性以芯片和设备 binding 为准。')
],['先把板级硬件描述和驱动操作逻辑分开，再把 DTS、DTC、DTB 放进启动链路。','按父总线的 cell 数解析 reg；按对应 binding 理解 clocks、interrupts、gpios 等引用。','内核枚举/匹配后才有机会调用驱动初始化；一个 okay 节点不等于设备已经工作。'],'下面代码仅演示 cell 与总线地址语义，不是可直接套用到任意板子的完整 DTS。',['父节点 address-cells=2、size-cells=1，reg=<0x0 0x40001000 0x100> 怎样拆？','前2个cell拼地址0x0000000040001000，后1个cell给长度0x100=256字节。该地址属于父总线地址空间，是否还需 ranges 转换要看树结构。'],[
 ['DTB 是什么？',['C头文件','二进制设备树','任务栈','驱动源码'],1,'DTC 把源码描述编译成二进制树。'],
 ['reg 的格式主要由谁约束？',['节点名长度','操作系统位数','父总线 cell 定义与 binding','编译器int大小'],2,'不能只数十六进制位或凭64位系统猜。'],
 ['status="okay" 能保证设备驱动成功吗？',['不能，还需匹配、资源与初始化成功','总能','自动生成驱动','自动修好接线'],0,'启用描述只是一环。']
],[13,14], '/* 仅演示片段；外层控制器须有真实平台 binding */\n#address-cells = <1>;\n#size-cells = <0>;\nsensor@48 {\n    compatible = "example,demo-temp";\n    reg = <0x48>;\n    status = "okay";\n};');
L('linux','linux-driver','10 · 驱动、probe、设备节点与排错','有了 /dev 文件，为什么 open 仍可能失败？没有 /dev 又说明什么？',[
 S('设备、驱动、节点是三层对象','设备对象描述一个实际/逻辑设备；驱动提供操作逻辑；/dev 下的字符或块设备节点是用户空间入口之一。设备节点的主次设备号用于找到相应处理对象，不是把寄存器地址写在文件名里。','并非所有驱动都创建 /dev 节点。网络设备、某些传感器子系统、内部总线控制器等有各自接口。也不能仅因为手动创建了一个节点，就认为内核里已存在可用驱动。'),
 S('probe 什么时候发生？','设备与驱动在对应总线上匹配后，驱动核心尝试绑定并调用 probe。probe 获取资源、初始化设备，并按所属子系统注册接口；匹配不等于 probe 成功。依赖尚未就绪时可能延后探测，具体遵循驱动核心与总线规则。','设备树 compatible 常与驱动匹配表有关；具体匹配路径还受总线和驱动注册方式影响。不要声称所有总线都只按 compatible 一个字段工作。'),
 T('从现象收集证据',['现象','下一步核对'],[['启动没有 probe 日志','实际DTB、节点启用、驱动配置/加载、匹配表'],['probe 返回资源错误','时钟、复位、GPIO、IRQ、电源和依赖'],['节点存在但 open 失败','errno、权限、主次设备号、驱动状态'],['read 卡住','是否阻塞模式、硬件事件、等待队列、设备是否有数据']]),
 S('用户空间与内核空间的边界','用户程序不能把指针直接当内核可信地址。字符驱动与用户交换数据要使用适当的用户访问接口并检查失败；MMIO 要用相应资源映射和访问接口。笔试先说明边界和资源生命周期，再讨论具体 API，避免背一段不适用于本平台的驱动模板。')
],['按设备枚举、驱动匹配、probe 初始化、用户接口建立的顺序推导。','根据失败发生在哪一步收集日志和 errno；不要把问题全归到文件权限。','验证加载的是对应固件/DTB/模块版本，随后核对硬件资源和电气连接。'],'并非所有 Linux 平台用设备树枚举；也存在 ACPI、PCI 自发现等路径。',['驱动模块加载成功，但没有 /dev/xxx，可以直接断言驱动坏了吗？','不能。先确认该驱动是否按设计提供 /dev 入口，再检查是否找到设备、probe 是否成功、是否已注册相应接口以及节点创建机制。'],[
 ['probe 与 match 的关系？',['匹配后才尝试probe','probe替代所有匹配','仅应用调用probe','只有main能调用'],0,'驱动核心按总线机制匹配并尝试绑定。'],
 ['所有驱动都会生成 /dev 吗？',['是','仅64位是','不是','只要DTS存在就会'],2,'取决于子系统提供的用户接口。'],
 ['手动创建设备节点等于？',['自动装好驱动','创建一个入口名称及设备号映射','硬件开始工作','自动调用fork'],1,'还必须存在支持该设备的内核实现。']
],[15,14]);
L('rtos','r-priority-basics','优先级从零讲：谁现在能运行？','先分清“有资格运行”和“先运行谁”，再判断调度结果。',[
 S('优先级不是 CPU 份额','本课限定单核 FreeRTOS、configUSE_PREEMPTION=1。任务优先级数值越大越高，合法范围通常为0到configMAX_PRIORITIES-1；Idle 为0。优先级3不意味着每秒运行3次，也不意味着占用30%的CPU。','就绪 Ready 表示已具备运行条件；阻塞 Blocked 表示等待数据或时间；运行 Running 表示正在用CPU。高优先级任务阻塞时没有资格参选，调度器会让较低优先级的就绪任务运行。'),
 S('为什么 while(1) 轮询会饿死低优先级？','高优先级H反复检查标志，但一直不阻塞，H便一直保持就绪。低优先级L可能一直拿不到CPU，即使L正是负责产生该标志的任务。把H改成等待队列/通知，在无工作时阻塞，L才有机会执行。','taskYIELD() 只是主动发起一次调度，H仍就绪且最高时仍可能选回H；它不能保证把CPU交给低优先级。忙等待与vTaskDelay也不同，后者让任务在相应时段不参与就绪竞争。'),
 T('三组容易混淆的设置',['设置/行为','实际意义'],[['configUSE_PREEMPTION=1','允许更高优先级就绪任务抢占（按移植层切换机制）'],['configUSE_TIME_SLICING=1','同优先级就绪任务通常可随 tick 轮转；不是不同优先级平均分配'],['关闭时间片','不代表永不切换，阻塞、主动yield等仍可能引发调度']]),
 S('怎样分配工程优先级？','先列截止时间、最坏执行时间、阻塞和依赖。控制环常比日志更紧急，但不能只按任务名称决定。任务执行快不代表优先级必须高；提升所有任务优先级也不会增加CPU算力。其他RTOS的数字方向可能不同，必须查具体系统。')
],['列出每个时刻的 Ready 集合，把阻塞和挂起任务排除。','在就绪任务中选最高优先级；同级再结合时间片、yield与阻塞事件。','检查高优先级是否持续占用CPU，以及锁依赖、超期和中断干扰。'],'以下例子只讨论单核抢占式 FreeRTOS；SMP、协作式或其他 RTOS 不能直接套结论。',['H=3，L=1，H一直就绪且循环taskYIELD，L一定运行吗？','不一定。yield不把H变为阻塞；它仍是最高优先级就绪任务。应使用真正的事件等待或合理延时，让H暂时退出竞争。'],[
 ['FreeRTOS 任务优先级3与1谁高？',['1','相同','3','由名字决定'],2,'任务数值越大优先级越高。'],
 ['优先级最高但阻塞的任务会？',['继续占CPU','暂不参与就绪竞争','自动退出','自动变中断'],1,'阻塞表示运行条件尚不满足。'],
 ['时间片通常在谁之间轮转？',['同优先级就绪任务','所有任务平均','只有阻塞任务','所有ISR'],0,'高低优先级不因时间片自动均分。']
],[16]);
L('rtos','r-priority-inversion','优先级反转：H 为什么在等 L？','一个低优先级任务持锁时，高优先级任务能直接抢走锁吗？',[
 S('先设定三个角色','H优先级3、M为2、L为1。共享资源有一把互斥锁。L先获得锁，再被H抢占；H也需要锁，所以只能阻塞等待L释放。此时H优先级高，也不能凭优先级越过资源保护。','如果M此时就绪，会抢占L。结果H间接被不使用该锁的M延迟，这就是典型优先级反转。光提高H的优先级没有解除“L必须先完成”的依赖。'),
 S('继承怎样缩短等待？','使用支持优先级继承的FreeRTOS Mutex时，H因等待L持有的锁而阻塞，可使L暂时获得H的高优先级。这样L能先于M运行，尽快退出临界区并释放锁，H随后继续。','提升的是持有者L，不是让等待者H在锁内并行执行。Mutex和普通二值信号量不可仅按“都是0/1”互换；二值信号量不提供同样的优先级继承语义。'),
 S('继承并不能包治百病','继承不能修复死锁：若两个任务各持一锁并相互等待，单纯调优先级也无法释放依赖。保持锁顺序一致、缩短持锁时间，避免持锁做不可控长等待。','FreeRTOS采用简化继承机制，持多把锁时恢复时机有具体限制，不能断言每释放任意一把锁都会立即恢复基础优先级。本课动画只使用一把锁，释放后按此简化场景分析。')
],['先画资源所有权：锁在谁手里，高优先级到底等待谁。','再看有没有中优先级任务抢占持有者，造成额外等待。','用Mutex继承缩短这部分干扰，同时检查持锁时长、锁顺序和多锁限制。'],'优先级继承减少反转带来的额外阻塞，不等于消除持锁本身的等待，更不等于死锁检测。',['把Mutex改成二值信号量，H等L时，L仍一定继承H优先级吗？','不一定且不能依赖它：FreeRTOS二值信号量不提供Mutex的优先级继承。保护共享资源应按所有权与继承需求选择Mutex。'],[
 ['继承时临时提高谁？',['持锁的L','等待的H再加一','无关的M','全部任务'],0,'让真正能解除阻塞的持有者尽快执行。'],
 ['优先级继承能自动解决死锁吗？',['能','只要H足够高','不能','只在32位能'],2,'循环资源依赖不会因调优先级消失。'],
 ['FreeRTOS 哪种原语提供所述继承？',['普通队列','Mutex','二值信号量','事件组'],1,'互斥锁具备资源所有权及继承语义。']
],[18]);
L('rtos','r-nvic-priority','任务优先级与 NVIC：数字方向相反','任务优先级5和中断优先级5，能直接比较谁先运行吗？',[
 S('这是两套不同系统','FreeRTOS任务优先级用于调度任务，数值越大越高。Cortex-M的NVIC中断优先级用于异常抢占，数值越小通常越紧急。不能把Task5与IRQ5放进同一张排序表，也不能认为任务数字大就能抢占ISR。','有效优先级位数和分组来自芯片/配置。抢占优先级决定能否打断；子优先级影响某些同时挂起的选择，不等于更深一层抢占。以下算例限定STM32常见Cortex-M3/M4、4个实现位、这些位全作抢占优先级。'),
 S('阈值5到底是哪边能调用API？','设未移位的库级阈值configLIBRARY_MAX_SYSCALL_INTERRUPT_PRIORITY=5。NVIC数值0到4更紧急，不允许调用FreeRTOS API；5到15才落在允许调用FromISR接口的范围。这里比较的是同一套未移位数值。','原因是内核临界区按阈值屏蔽允许访问内核的那一组中断。更紧急中断仍可能打断临界区，若它也修改内核结构，就可能破坏一致性。因此不是“越紧急越有权调任何API”。'),
 T('4个实现位时，别混两种编码',['用途','示例'],[['CMSIS/HAL输入（按对应API约定）','未移位优先级5'],['写入优先级寄存器高位的编码','5 << (8-4) = 0x50'],['FreeRTOS移植层阈值宏','configMAX_SYSCALL_INTERRUPT_PRIORITY 常用已移位编码；核对移植层']]),
 S('FromISR 不是免检查通行证','还要确认ISR优先级合法、不请求阻塞、检查队列满等失败，并按移植层用portYIELD_FROM_ISR请求必要的切换。被唤醒任务通常在退出中断的调度路径中运行，而不是在ISR函数里直接跑任务体。Cortex-M0等不同端口不能照搬BASEPRI模型。')
],['先判断正在比较任务还是中断；不同体系不能直接排大小。','把NVIC位数、分组和是否移位写在纸上；同单位比较阈值。','ISR使用允许的FromISR接口，检查返回值并正确请求切换，任务负责较重处理。'],'逻辑紧急程度“更高”对应NVIC数字“更小”；优先级0常是默认值，若没配置就调用API可能违反约束。',['上述阈值5场景，IRQ=3和IRQ=7哪个可调用xQueueSendFromISR？','IRQ=7可以在满足其他条件时调用，IRQ=3不可以。3更紧急且可能打断内核临界区；7处于5到15允许区间。任务优先级不参与这个判断。'],[
 ['NVIC数值2与7，通常谁更紧急？',['7','一样','2','看任务栈'],2,'数值越小紧急程度越高。'],
 ['题设阈值5，哪个中断可调用FromISR？',['0','3','4','8'],3,'8处于允许的数值区间5..15。'],
 ['4个实现位时，5的移位编码是？',['0x50','0x05','0x500','0x0F'],0,'5左移4位，得到80即0x50。']
],[17]);
L('ds','ds-valley','波谷题入门：严格波谷与平底波谷','“波谷”不是唯一题目名，先把题目定义翻译成不等式。',[
 S('先用折线读懂低点','把下标i放在横轴，把a[i]放在纵轴。严格内部波谷要求a[i-1]>a[i]并且a[i]<a[i+1]，即左边下降到它，右边从它上升。例[5,2,6]的下标1是波谷。它只比左右邻居低，不要求是全数组最小值。','本课下标从0开始，首尾因缺少一侧邻居不算严格内部波谷。若原题把两端当无穷大，答案就会不同；笔试不能自行补这个条件。'),
 T('相等值会改变题目',['数组','严格内部波谷个数','把平底算一个波谷'],[['[5,2,6]','1','1'],['[5,2,2,6]','0','1'],['[2,2,2]','0','0'],['[1,3,1]','0（首尾不算）','0']]),
 S('严格波谷为什么只需一遍？','每个候选只依赖三个相邻值，遍历i=1到n-2即可。使用直接比较，不写(a[i-1]-a[i])>0，避免极端整数相减溢出。长度不足3直接返回0。每个位置检查常数次，时间O(n)、额外空间O(1)。'),
 S('平底波谷怎样避免重复数？','把一段连续相等值压成一个“平台”[l,r]。只有l>0、r+1<n且a[l-1]>a[l]、a[r+1]>a[r]，才算一个。扫完平台就从r+1开始，这样[5,2,2,2,6]不会把中间三个2各计一次。','如果题目只要求“找到任意一个局部最小值”并保证相邻不等，还可研究二分；但二分找一个不等于统计全部，不能把O(log n)模板直接套到计数题。')
],['先写清严格/非严格、端点、平台、下标基准和返回目标。','严格版逐三元组比较；平台版先合并连续相等段，再比较平台两边。','用单调、全相等、短数组和多波谷验证，不要只测试一个V形。'],'这些是原创常见题型练习，不声称就是你今天的原题；最长连续区间与波谷计数是不同问题。',['数组[6,3,5,2,2,7]，严格波谷和平台波谷各几个？','严格版1个（下标1，值3）；平台版2个，另一个是[3,4]的两个2。严格版中相等邻居破坏<条件。'],[
 ['严格内部波谷条件为？',['比全数组都小','大于左右','只小于左','小于左右两个邻居'],3,'是局部条件，不是全局最小值。'],
 ['[4,1,1,3] 严格波谷数量？',['0','1','2','4'],0,'两个1都有一个相等邻居，均不满足严格小于。'],
 ['统计全部严格波谷的直接复杂度？',['O(log n)','O(n)','O(n²)','O(1)'],1,'逐位置一次扫描。']
]);
L('ds','ds-valley-longest','波谷题进阶：最长先降后升连续区间','要求最长长度时，为什么仅数最低点不够？',[
 S('把目标与连续性写清','本课寻找最长连续子数组：先严格下降至少一步，再严格上升至少一步；相等会打断，长度至少3。返回长度，没有则0。子数组要求连续，子序列可以跳过元素，两个问题不能混用。','[8,6,3,4,7]整体是长度5的谷；[1,2,3]没有下降段，答案0；[5,2,2,4]有相等打断，答案0。最长谷不一定以全局最小值为底。'),
 S('以谷底为中心，算两侧长度','down[i] 表示以i结束的严格下降连续段长度：若a[i-1]>a[i]，就是down[i-1]+1，否则1。up[i] 表示从i开始的严格上升连续段长度：从右向左算，若a[i]<a[i+1]，就是up[i+1]+1，否则1。','若down[i]>1且up[i]>1，左右坡都存在，候选长度为down[i]+up[i]-1。减1是因为谷底被两边都算了一次。两个数组各一遍，再枚举谷底，时间O(n)、空间O(n)。这是容易验证的第一版。'),
 S('怎样优化到常数额外空间？','只保留当前谷的下降边数down、上升边数up。遇下降且此前在上升，就结束旧谷，从当前位置的新下降边重新开始；遇相等则两者归零；遇上升且down>0，则up增加并更新down+up+1。','边数和元素数不同：2条下降边+2条上升边对应5个元素，故+1。这与数组版“左右都含谷底，所以-1”不矛盾。先用图逐步走，再尝试常数空间练习。')
],['先验证连续、严格、两侧至少一条边这三个条件。','用左右长度数组建立可检查的递推式；只在两侧都存在时更新答案。','再用状态只保留当前下降/上升边数；上升转下降时允许新谷从相邻峰顶重新开始。'],'本课不讨论可删除元素的最长谷形子序列；那通常需要另一套动态规划，答案可能不同。',['[9,7,4,6,8,3,5] 的最长谷长多少？','5，对应[9,7,4,6,8]。后面的[8,3,5]长3。两个谷可以共用峰顶8，但不能把上升再下降拼成一个先降后升区间。'],[
 ['down=3、up=4且都含谷底，长度？',['7','12','6','5'],2,'谷底重复一次，所以3+4-1=6。'],
 ['[4,3,2] 的最长严格谷长度？',['3','2','1','0'],3,'没有上升坡，不能构成谷。'],
 ['相等元素在本课定义下会？',['打断严格坡段','自动删去','算下降','算上升'],0,'严格不等式不允许相等。']
]);

// One harder multiple-choice problem per new lesson. Correct option identities remain stable.
function M(lesson,prompt,options,answer,steps,code=''){
 expansionChoices.push({id:'extra-exam-'+lesson,lesson,prompt,options,answer,steps,code,explain:steps.join('\n'),difficulty:'进阶',source:'原创笔试题'});
}
M('linux-start','两个线程各执行1000次无同步的普通C变量count++，能保证最终2000吗？',['能，int访问快','不能，存在数据竞争','只要volatile就能','只要同一进程就能'],1,['count++不是一个不可分割的同步操作。','C中未同步的冲突访问可构成数据竞争，不能只预测某个较小整数。','使用适当互斥锁或原子操作，并保证线程完成后再读取。']);
M('linux-shell','cmd 2>&1 >out 与 cmd >out 2>&1 在一般Shell中有何差别？',['完全一样','前者stderr指向原stdout，后者两者指向out','前者只输出错误','后者只输出正常信息'],1,['重定向从左到右生效。','2>&1复制当时的1，而非建立永久跟随关系。','之后再改变1不会追溯改变已经复制的2。']);
M('linux-fork','所有fork成功，无提前退出，最终包含原进程共有几个？',['2','3','4','5'],1,['第一次fork父返回正数，&&还要执行右侧fork。','第一次的子返回0，短路跳过右侧。','原父的第二次fork再产生一个子，共3个；if体为空不影响数量。'],'if (fork() && fork()) { /* empty */ }');
M('linux-exec','execvp("echo",args)中args={"echo","hi",">","out",NULL}，哪项正确？',['自动重定向到out','必须产生两个进程','>通常作为普通参数交给echo','exec返回0后才打印'],2,['execvp本身不执行Shell语法解析。','这里把>和out作为参数字符串传入。','若需要重定向，应由Shell解析或显式open/dup2；exec成功不返回。']);
M('linux-wait','waitpid(pid,&s,WNOHANG)返回0后立即WEXITSTATUS(s)，问题是什么？',['0已经表示成功退出','此次未收集到状态，不应当作有效退出码解码','需要先fork两次','WNOHANG会杀子进程'],1,['0意味着此刻无可报告状态。','即使返回正数，也先检查WIFEXITED。','此路径应该继续按事件/时间策略等待，避免忙轮询。']);
M('linux-fd','a=open同一普通文件，b=dup(a)，c=另一次open；a成功读3字节后，b与c偏移一般为？',['3和0','0和0','3和3','0和3'],0,['b和a引用同一打开文件描述，所以b偏移3。','c来自独立open，偏移独立，仍0。','题设无其他lseek/read并发修改且初始偏移0。']);
M('linux-ipc','父子均持管道写端；父写完关闭，子读空后阻塞，最直接原因是？',['read只能读一次','子仍持写端，EOF条件没满足','父必须exec','必须调高子优先级'],1,['EOF要求所有写端引用关闭且数据读空。','子不写数据也必须关闭继承的写端副本。','只关闭父端并不足以满足引用计数条件。']);
M('linux-io','ET套接字可读后读4/10字节就重新等待，可能出现？',['剩余6字节被内核删除','应用等待而缓冲仍有未读数据','必定再通知6次','自动切换LT'],1,['ET关注状态变化，不能依赖未读存量持续重复通知。','非阻塞循环读到EAGAIN可确认已排空。','同时处理EOF、EINTR与真正错误，并维护协议状态。']);
M('linux-devicetree','父#address-cells=2、#size-cells=1，reg=<0x1 0x20 0x80>代表？',['地址0x1、长度0x20','地址0x100000020、长度128字节','地址0x20、三个区域','长度由sizeof(long)决定'],1,['两个32位cell组成地址，高32位1、低32位0x20。','最后一个cell是长度0x80=128。','这是父总线地址，实际物理地址还可能需要ranges转换。']);
M('linux-driver','设备树节点启用、驱动模块加载成功，但没有probe成功记录，应该？',['先创建/dev就一定修好','直接把所有寄存器清零','核对实际DTB、总线匹配和probe错误/依赖','只能提高任务优先级'],2,['模块加载与设备实例成功绑定不是同一事件。','确认启动用的DTB、compatible和驱动匹配表。','匹配后再看probe资源获取、依赖延后等日志。']);
M('r-priority-basics','H=4、L=1，H无限taskYIELD，单核抢占式且H始终Ready，L一定运行吗？',['会，yield强制轮到L','不会得到保证','每4tick一次','每1tick一次'],1,['yield触发选择，不会使H阻塞。','H仍是最高优先级就绪任务，可以再次被选中。','无工作时应通过事件等待等机制阻塞。']);
M('r-priority-inversion','单锁场景L持Mutex、H等待、M就绪，继承后谁需要先执行才能解除H的等待？',['H绕过锁','M替L解锁','L临时提高优先级完成临界区','全部同时写资源'],2,['资源在L手里，H必须等待释放。','提高L可避免无关M继续抢占它。','继承不允许H跳过互斥保护。']);
M('r-nvic-priority','4个有效位且全部抢占位，库级阈值5；IRQ逻辑优先级4用FromISR是否合规？',['合规，因为4小于5','不合规，4更紧急且不在允许区间','只需任务优先级高于4','只有队列满才违规'],1,['比较未移位值，合法调用区间5..15。','4在0..4的更紧急范围，会打断内核临界区。','FromISR命名不能免除优先级约束。']);
M('ds-valley','[5,2,2,6,1,4]的严格波谷数与平台波谷数分别是？',['2和2','1和2','0和2','1和1'],1,['严格版只有下标4的1比两邻居都小。','下标1..2的2是平底，不符合严格版。','平台版该平台两侧5和6都更大，因此额外计1。']);
M('ds-valley-longest','[7,5,3,4,6,2,8]最长先严格降后严格升连续段长度？',['7','4','5','3'],2,['[7,5,3,4,6]长5。','后面的[6,2,8]长3。','不能跨越6之后再次下降，把两个谷合为一个。']);
function W(id,lesson,title,prompt,answer,steps,rubric,code=''){
 expansionWritten.push({id:'extra-written-'+id,lesson,title,prompt,answer,steps,rubric,code,kind:'推导与改错',difficulty:'进阶',source:'原创笔试题'});
}
W('fork-tree','linux-fork','画出条件 fork 的进程树','假设所有fork成功：执行代码后有几个进程？每个最终x是什么？','3个进程；父P的x=1，子C与孙D的x均为2。',['第一次fork只有子分支进入if。','子把自己的x改2，再复制出孙；父的私有x不变。','谁先到最后不确定，不能预测输出顺序。'],['进程树3分','变量各自值3分','顺序与失败前提2分'],'int x=1;\nif(fork()==0){ x=2; fork(); }\n/* 此处观察每个进程的x */');
W('exec-fail','linux-exec','exec 后为什么一定要处理失败？','子分支调用execvp后，直接继续执行父进程主循环有什么风险？给出失败处理思路。','成功不会回来；回来说明失败，应记录适当错误并以选定状态结束子分支，父负责回收。',['子不应因exec失败意外再运行父主循环、重复创建子进程。','单线程示例可perror后_exit(127)；多线程fork子路径要限制为异步信号安全操作。','父用waitpid区分正常退出和信号终止；127是约定，不是exec的返回值。'],['成功/失败语义3分','子错误路径3分','父回收与多线程限制2分']);
W('fd-map','linux-fd','画出三个 fd 的共享关系','a=open后b=dup(a)，c另一次open。关闭a后b还能用吗？它和c共享偏移吗？','b通常仍可用；b与已关闭a原来共用的打开文件描述仍有引用。c来自独立open，偏移独立。',['fd是表项索引，不是文件本体。','关闭a只去掉一个引用，不会自动使b的描述符失效。','画两份打开文件描述，b指第一份，c指第二份。'],['引用关系3分','关闭影响2分','偏移独立2分']);
W('pipe-eof','linux-ipc','设计父写子读的关闭顺序','pipe后fork：逐项列出父子应关闭哪些端点，以及如何让子读到EOF。','父关p[0]，写完关p[1]；子关p[1]，循环读p[0]到0再关；父最终waitpid。',['fork使两个进程都继承两端。','子自己持写端也会阻止EOF；必须关闭不用端点。','处理短读短写和EINTR，失败路径同样清理描述符、回收子进程。'],['端点关闭4分','EOF前提2分','错误与回收2分']);
W('dt-reg','linux-devicetree','同一个 reg 为什么含义不同？','对比父cell配置(1,0)的I²C子节点reg=<0x48>，与(1,1)的内存映射子节点reg=<0x4000 0x100>。','前者通常是I²C从机地址0x48，没有长度cell；后者是总线地址0x4000、长度256。',['先读取父address-cells与size-cells。','再按总线binding解释地址空间，不把I²C地址当CPU指针。','内存映射的最终CPU物理地址还需检查ranges等转换。'],['分组解析3分','两种地址语义3分','转换前提2分']);
W('schedule','r-priority-basics','按事件填写运行任务','单核抢占式A=3、B=2、C=1。起初全Ready；A等队列阻塞；B延时；ISR唤醒A并正确请求切换。逐步填运行者。','A → B → C → 退出ISR后A。',['每一步先排除阻塞任务。','在剩余Ready任务中选数值最高者。','A由事件变为Ready，在正确的中断退出调度路径抢占C；不是ISR内部执行A函数。'],['四阶段4分','Ready集合2分','切换时机2分']);
W('inversion','r-priority-inversion','用三任务解释反转与继承','H=3、M=2、L=1；L持单把Mutex，H等待它，M就绪。分别说明无继承/有继承时的运行依赖。','无继承M可抢占L，H间接被M拖延；继承后L临时提升至H优先级，先完成临界区解锁。',['H等待的是锁，所以自己优先级再高也不能直接使用资源。','L是唯一能解除这条依赖的持有者，提高L才有帮助。','单锁示例释放后H继续，L恢复基础优先级；多锁恢复按FreeRTOS实际机制，继承不解决死锁。'],['反转链路3分','继承对象3分','限制2分']);
W('nvic','r-nvic-priority','算优先级编码并检查 API 调用','4个实现位全作抢占位，库级阈值5。IRQ3与IRQ8分别是否能调FromISR？阈值寄存器编码是多少？','IRQ3不能，IRQ8可在满足其他条件时调用；阈值编码0x50。',['NVIC小数字更紧急，0..4高于允许调用内核的逻辑阈值。','移位是5<<(8-4)，得80即0x50。','仍需用正确FromISR接口、检查失败并请求必要切换，不能阻塞。'],['范围判断3分','编码计算2分','ISR条件3分']);
W('valley-spec','ds-valley','先问定义，再写算法','题干只有“统计波谷”，至少要补问哪些条件？用[4,1,1,3]解释一种歧义。','确认严格或平台、端点是否算、返回数量/下标/最长长度、连续或子序列及范围。该数组严格版0，平台版1。',['相等邻居不满足严格小于。','若合并平底连续段，其左右均更高，所以平台版算1。','不同定义有不同算法，不能因样例看起来像V就默认规则。'],['关键条件4分','两结果2分','算法与定义对应2分']);
